3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Derives the deterministic {@code householdId}: the first 12 hex characters of
12	 * {@code SHA-256(normalizedLastName + '|' + postcode)}.
13	 *
14	 * <p>Because it depends only on the last name and postcode, every owner sharing those two values
15	 * resolves to the same id automatically, without any request opting in and without back-filling
16	 * other members. The last name is normalized case-insensitively with runs of whitespace collapsed;
17	 * the postcode is trimmed and contributes an empty segment when absent.
18	 */
19	public final class Households {
20	
21	    private Households() {
22	    }
23	
24	    /** The householdId for the owner, derived from its last name and postcode. */
25	    public static String id(Owner owner) {
26	        return id(owner.getLastName(), owner.getPostcode());
27	    }
28	
29	    /** The householdId for the given last name and postcode. */
30	    public static String id(String lastName, String postcode) {
31	        String input = normalize(lastName) + '|' + segment(postcode);
32	        try {
33	            byte[] digest = MessageDigest.getInstance("SHA-256")
34	                    .digest(input.getBytes(StandardCharsets.UTF_8));
35	            StringBuilder sb = new StringBuilder(12);
36	            for (int i = 0; i < 6; i++) {
37	                sb.append(String.format("%02x", digest[i]));
38	            }
39	            return sb.toString();
40	        }
41	        catch (NoSuchAlgorithmException e) {
42	            throw new IllegalStateException("SHA-256 not available", e);
43	        }
44	    }
45	
46	    /**
47	     * The size of the owner's household: the number of persisted owners sharing this owner's
48	     * {@code householdId} (members inclusive). Returns 0 when the owner has no household id.
49	     */
50	    public static long size(Owner owner, OwnerRepository repository) {
51	        String householdId = owner.getHouseholdId();
52	        if (householdId == null) {
53	            return 0;
54	        }
55	        return repository.findAll().stream()
56	                .filter(existing -> householdId.equals(existing.getHouseholdId()))
57	                .count();
58	    }
59	
60	    private static String normalize(String value) {
61	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
62	    }
63	
64	    private static String segment(String value) {
65	        return value == null ? "" : value.trim();
66	    }
67	}
