9	public class DuplicateIdentityExceptionHandler {
10	
11	    public void handle(@Parameter DuplicateIdentityException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
14	                "An owner with the same identityKey already exists");
