package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a soft-match duplicate, keyed on the computed {@link Households#id(Owner) householdId}. A
 * new owner that shares an existing owner's household (same last name and postcode) but carries a
 * different telephone is created with {@code possibleDuplicate} set true and {@code possibleDuplicateOf}
 * set to the matching owner's id.
 *
 * <p>A declared household member (request {@code sharesHousehold} true) is NOT a suspected duplicate:
 * it deliberately joins an existing household, so it is created with {@code possibleDuplicate} false.
 * Any other owner reaching this step is not a household duplicate ({@link EnsureUniqueIdentity} has
 * already rejected those), so it too is left unflagged.
 *
 * <p>Runs before {@link SaveOwner} so the new owner has not been persisted yet and is not compared
 * against itself. The earliest matching owner (lowest id) is chosen for stability.
 */
public class AssignPossibleDuplicate {

    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(sharesHousehold)) {
            // Declared household member: a deliberate join, not a suspected duplicate.
            owner.setPossibleDuplicate(Boolean.FALSE);
            return;
        }
        String householdId = owner.getHouseholdId();
        String telephone = owner.getTelephone();
        Owner match = ownerRepository.findAll().stream()
                .filter(existing -> !existing.getId().equals(owner.getId()))
                .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted())) // ignore soft-deleted owners
                .filter(existing -> householdId.equals(Households.id(existing))
                        && !equalsIgnoreCase(existing.getTelephone(), telephone))
                .min(java.util.Comparator.comparing(Owner::getId))
                .orElse(null);
        if (match != null) {
            owner.setPossibleDuplicate(Boolean.TRUE);
            owner.setPossibleDuplicateOf(match.getId());
        }
        else {
            owner.setPossibleDuplicate(Boolean.FALSE);
        }
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The owner duplicate block, expressed through the {@link OwnerIdentity#key(Owner) identityKey}
 * (normalized telephone + email + householdId). A second owner whose whole key matches an existing
 * one is a duplicate and is rejected (409); because the telephone is part of the key, two members of
 * the same household with different telephones have distinct keys and are both allowed.
 *
 * <p>The request's {@code sharesHousehold} flag bypasses this block: a declared household member is
 * created even when its identity key already exists. Runs after {@link AssignHousehold} so the new
 * owner's {@code householdId} (and hence its identity key) is set; existing owners are compared by
 * their own computed key.
 */
public class EnsureUniqueIdentity {

    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        if (Boolean.TRUE.equals(sharesHousehold)) {
            return; // declared household member: allowed to join an existing household
        }
        String identityKey = OwnerIdentity.key(owner);
        boolean inUse = ownerRepository.findAll().stream()
                .filter(existing -> !existing.getId().equals(owner.getId()))
                .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted())) // ignore soft-deleted owners
                .anyMatch(existing -> identityKey.equals(OwnerIdentity.key(existing)));
        if (inUse) {
            throw new DuplicateIdentityException(
                    "An owner with identity key " + identityKey + " already exists");
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId} (see {@link Households}): the first 12 hex
 * characters of {@code SHA-256(normalizedLastName + '|' + postcode)}.
 *
 * <p>The id is derived from the last name and postcode alone, so every owner at the same last name
 * and postcode resolves to the same value automatically. It is assigned unconditionally — the
 * request's {@code sharesHousehold} flag no longer creates the link, it only bypasses the household
 * duplicate block in {@link EnsureUniqueIdentity}.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Households.id(owner));
    }
}

